// Reconciler. Folds every agent report back onto the blackboard and records
// which agents failed, so the answer can say what is missing instead of
// quietly producing a thinner answer.
const ctx = $('Blackboard: shared context').first().json;

const findings = [];
const evidence = [];
const trace = [...(ctx.classify_trace || [])];
const agentsReported = [];
const agentsFailed = [];

for (const item of $input.all()) {
  const j = item.json || {};

  // a branch isolated by onError:continueRegularOutput carries `error`
  if (j.error || j.__isolated) {
    agentsFailed.push(j.domain || j.agent || 'unknown agent');
    continue;
  }
  if (!j.domain && !j.agent) continue;

  agentsReported.push(j.agent || j.domain);
  if (j.findings && Object.keys(j.findings).length) findings.push(j.findings);
  if (Array.isArray(j.evidence)) evidence.push(...j.evidence);
  if (Array.isArray(j.trace)) trace.push(...j.trace);
}

// de-duplicate evidence by id; every branch runs the same planner pass, so
// position and window evidence overlaps between agents
const seen = new Set();
const uniqueEvidence = [];
for (const e of evidence) {
  if (!e || !e.id || seen.has(e.id)) continue;
  seen.add(e.id);
  uniqueEvidence.push(e);
}

if (agentsFailed.length) {
  trace.push({
    seq: 0,
    agent: 'orchestrator',
    action: `${agentsFailed.length} agent(s) were isolated after failing`,
    rationale: 'one dead upstream must not sink the request; the answer says what is missing',
    outcome: agentsFailed.join(', '),
    status: 'degraded',
    duration_ms: 0,
    evidence_ids: [],
  });
}

trace.push({
  seq: 0,
  agent: 'orchestrator',
  action: `reconciled ${agentsReported.length} agent report(s) on the blackboard`,
  rationale: 'n8n ran the specialist agents in parallel; their findings are merged before the risk rules see them, so risk assessment reads exactly the same evidence as the in-process path',
  outcome: `${findings.length} finding blocks, ${uniqueEvidence.length} unique evidence items`,
  status: 'ok',
  duration_ms: 0,
  evidence_ids: [],
});

// renumber so the reasoning panel reads in order
trace.forEach((step, i) => { if (step) step.seq = i + 1; });

return [{
  json: {
    message: ctx.message,
    session_id: ctx.session_id,
    lat: ctx.lat,
    lon: ctx.lon,
    place: ctx.place,
    destination: ctx.destination || null,
    intent: ctx.intent,
    agents_reported: agentsReported,
    agents_failed: agentsFailed,
    findings,
    evidence: uniqueEvidence,
    trace,
    allow_llm: true,
  }
}];

// Small talk and self-description need no retrieval at all. Hand the
// supervisor's plan straight to synthesis with an empty evidence set.
const ctx = $json;
return [{
  json: {
    message: ctx.message,
    session_id: ctx.session_id,
    lat: ctx.lat,
    lon: ctx.lon,
    place: ctx.place,
    destination: ctx.destination || null,
    intent: ctx.intent,
    agents_reported: [],
    agents_failed: [],
    findings: [],
    evidence: [],
    trace: ctx.classify_trace || [],
    allow_llm: true,
  }
}];

// Critic agent. The one thing that must never go wrong is a rewrite that
// softens an unsafe verdict, so a second pass checks the answer against the
// verdict the rules produced. This is the n8n mirror of the in-process
// verdict guard, and it also catches an empty or evidence-free answer.
const r = $json || {};
const band = (r.risk && r.risk.band) || 'unknown';
const answer = (r.answer || '').trim();
const language = r.language || 'en';
const notes = [];

if (answer.length < 20) {
  notes.push('the answer is empty or too short to be useful');
}

if (band === 'unsafe' && r.llm_used) {
  const negative = ['do not', "don't", 'avoid', 'stay in', 'not safe', 'unsafe',
                    'remain in harbour', 'remain in harbor', 'postpone'];
  const lowered = answer.toLowerCase();
  const kept = negative.some((m) => lowered.includes(m));
  // The backend guard only enforces these markers for English. For a
  // translated answer the critic cannot read the wording, so it insists on a
  // deterministic re-run rather than trusting it.
  if (language === 'en' && !kept) {
    notes.push('an unsafe verdict lost its negative wording in the rewrite');
  } else if (language !== 'en') {
    notes.push(`an unsafe verdict was rewritten into ${language}, which cannot be verified here`);
  }
}

const ranAgents = ($('Reconciler: fold reports, flag gaps').isExecuted
  ? ($('Reconciler: fold reports, flag gaps').first().json.agents_reported || [])
  : []);
if (ranAgents.length && (r.evidence || []).length === 0) {
  notes.push('agents reported but no evidence reached the answer');
}

return [{ json: { ...r, critic_approved: notes.length === 0, critic_notes: notes } }];

// One bounded repair attempt: re-run synthesis with the model switched off, so
// the answer falls back to the deterministic template built from the same
// evidence. Bounded on purpose. No loop, no second guess, no model.
const rejected = $json;
const src = $('Reconciler: fold reports, flag gaps').isExecuted
  ? $('Reconciler: fold reports, flag gaps').first().json
  : $('Shortcut: no retrieval needed').first().json;

const trace = [...(src.trace || [])];
trace.push({
  seq: trace.length + 1,
  agent: 'critic',
  action: 'rejected the synthesised answer and demanded a deterministic re-run',
  rationale: 'the safety verdict must survive the wording pass unchanged',
  outcome: (rejected.critic_notes || []).join('; '),
  status: 'degraded',
  duration_ms: 0,
  evidence_ids: [],
});

return [{ json: { ...src, trace, allow_llm: false } }];
